insert into public.products (id, name, tag, kind, status, blurb, highlights) values
  ('drone', 'Aerial Drone Inspection', 'Aerial', 'Product', 'Active', 'Visual, thermal and ultrasonic-thickness drone inspection of flare stacks, tanks, structures and pipelines, including OGI/methane monitoring.', array['Visual, thermal and contact-UT sensor payloads on one flight programme', 'OGI/methane detection for flare and fugitive-emissions compliance', 'BVLOS-capable for long pipeline right-of-way runs', 'Removes personnel from height and confined-space exposure']::text[]),
  ('rov', 'ROV Subsea Inspection', 'Subsea', 'Product', 'Active', 'Work-class and observation-class ROV inspection of platform legs/jackets, subsea pipelines, FPSO hulls and mooring/SPM systems.', array['Work-class and observation-class vehicles for shallow to mid water depths', 'CVI, CP survey and NDT-ready tooling on the same vehicle', 'FPSO hull, riser, mooring and SPM/PLEM coverage', 'No diver mobilisation required']::text[]),
  ('crawler', 'Crawler Confined-Space Inspection', 'Confined-Space', 'Product', 'Active', 'Magnetic and tracked crawler robots for zero-man-entry inspection of tanks, pressure vessels and ductwork.', array['Zero-man tank entry — no confined-space permit required for the crew', 'API 653-aligned tank-floor and shell UT scanning', 'Fits vessel and ductwork geometries down to ~200mm', 'Full-coverage defect mapping, not spot checks']::text[]),
  ('cleaning', 'Robotic Tank & Hull Cleaning', 'Cleaning', 'Offer', 'Active', 'Marine-growth removal and in-service tank cleaning using articulated brush and jet-based ROV/crawler tooling.', array['Articulated brush heads conform to angled jacket members', 'In-service tank cleaning — no shutdown required', 'Reduces structural loading and corrosion risk from biofouling', 'Bundles with inspection for a single mobilisation']::text[]),
  ('platform', 'Digital Asset-Integrity Platform', 'Data', 'Offer', 'Pilot', 'A single data layer fusing drone, ROV and crawler findings into defect trending and inspection-cycle planning.', array['One record across drone, ROV and crawler datasets', 'Defect trending across inspection cycles, not just single reports', 'Built to plug into existing RBI programmes', 'Exportable reporting for regulator and JV-partner sign-off']::text[]),
  ('surveillance', 'Pipeline ROW Drone Surveillance', 'Security', 'Offer', 'Planned', 'Long-range BVLOS drone patrol for pipeline right-of-way security, encroachment and vandalism detection.', array['Long-range BVLOS patrol of pipeline right-of-way', 'Encroachment, illegal-tap and vandalism detection', 'Complements structural inspection lines already offered', 'Positions against incumbent security-only drone vendors']::text[])
insert into public.companies (id, name, type, priority, stage, summary, notes, pain_points, current_solutions) values
  ('amni', 'Amni International Petroleum', 'Indigenous — Private E&P', 'medium', 'research', 'Privately held Nigerian E&P operating Ima, Okoro and Setu (OML 112/117) plus Tubu (OML 52), and the Central Tano exploration block in Ghana. Shallow water (7–14m) across the Nigerian portfolio. A $2.5bn five-year development plan is underway, with the Okoro drilling campaign mobilised March 2026.', 'No named Asset Integrity contact — enter via the Offshore Installation Manager or Asset Management & External Relations.', array['FPSO Armada Perkasa (on station since 2008) has no public dry-dock or inspection record since a 2014 update', 'Okoro platform is an unconventional CoSMOS structure — conductor-supported, no steel jacket', 'Tubu (OML 52) is an unmanned, remotely operated wellhead platform 11km from its host — hard to reach manually', 'No evidence anywhere of a drone, ROV or robotic inspection programme in place']::text[], array['FPSO O&M handled by Bumi Armada (Malaysia) under bareboat charter', 'ABS classification society surveys', 'No named inspection-robotics vendor identified']::text[]),
  ('totalenergies', 'TotalEnergies (Nigeria Upstream)', 'Major IOC', 'high', 'research', 'Operates the Egina & Akpo FPSOs (OML 130), Amenam/Ikike (OML 99), Ofon (OML 102) and onshore OML 58/Ubeta. The AUSEA drone programme (renewed Aug 2026) proves drone trust in-country — but it covers methane detection only, leaving structural inspection untouched.', 'Procurement runs through NipeX — vendor pre-qualification is the realistic route in alongside direct outreach.', array['AUSEA drone programme covers methane detection only — no structural or topside inspection use of drones found', 'No public leak or integrity-audit data for Egina, Akpo, Amenam, Ofon or Ikike', 'Akpo down 18% YoY and Egina down 25% YoY (early 2026) amid a resumed drilling/intervention campaign — rising workover activity likely', 'Subsea/topside inspection is still vessel-and-personnel based (marine surveys, in-house OIMR, SEWOP)']::text[], array['AUSEA proprietary methane-detection drone (with CNRS / Univ. of Reims) — emissions only', 'LOC Group / AqualisBraemar LOC marine warranty surveys (Egina, 2014–2019)', 'In-house Subsea Support & Intervention Engineers running OIMR vessel campaigns', 'Rope-access NDE performed in-house']::text[]),
  ('seplat', 'Seplat Energy Plc', 'Indigenous — NGX/LSE Listed', 'high', 'contact', 'Dual-listed indigenous major; acquired ExxonMobil’s shallow-water JV (MPNU) Dec 2024 and is now ~70% offshore. Offshore platforms have been onstream since 1970. The Yoho platform fire (Sept 2025) forced a quarter offline.', 'Godwin Ibe is a verified, title-matched entry point. Current NIPEX contracts run 3+2 years from Q4 2025 — position as a complementary technology partner rather than a full displacement bid.', array['OML 67/68/70 platforms onstream in 1970 (~55 years old); OML 104 (Yoho) from 2002', 'Yoho Production Platform fire, 27 Sept 2025 — offline all of Q4 2025', '70% of the 600+ wells acquired with MPNU were not producing at handover', '2026 guidance explicitly flags “planned downtime for strategic maintenance and integrity activities”']::text[], array['Corrosion Condition Monitoring Services (NIPEX SEPLAT.00000125) — rope-access + manual/automated NDT, 3yr+2yr, from Q4 2025', 'Corrosion Control & Prevention Call-Off Services (NIPEX SEPLAT.00000123) — coating, CP, composite wrap', 'Two offshore integrity barges contracted from Q2 2025 (method undisclosed)', 'No drone, ROV or robotic crawler mentioned anywhere in current contracts']::text[]),
  ('nestoil', 'Nestoil Ltd', 'Indigenous EPC Conglomerate', 'low', 'hold', 'Obijackson Group’s EPC/O&M flagship (via IMPAC Engineering) and 45% owner of OML 42 via Neconde. HQ sealed by court order Oct 2025 amid a $1bn+ debt dispute; a Receiver/Manager was appointed and litigation continued into mid-2026.', 'Do not pursue commercially until Aerosub’s legal/sales leadership confirms counterparty authority. If pursued later, IMPAC Engineering (the O&M subsidiary) is the natural channel-partner entry point rather than direct contracting.', array['Contracting/signing authority is currently unsettled between company management and the court-appointed Receiver', 'No specific inspection or integrity contract or technology could be verified publicly', 'OML 42 technical condition is undisclosed — all coverage is legal/receivership-focused']::text[], array['No named inspection-robotics vendor or technology identified', 'EWT fabrication arm holds ISO 9001:2015 / ASME stamps — a construction, not inspection, orientation']::text[]),
  ('geil', 'Green Energy International', 'Indigenous — Private', 'medium', 'contact', 'Builder/operator of the Otakikpo terminal (OML 11) — Nigeria’s first indigenous onshore crude export terminal in 50+ years, commissioned Oct 2025. The brand-new offshore export system (SPM/SAL, PLEM, subsea pipeline) is a strong ROV fit.', 'Olawale Adenuga’s title explicitly combines Operations and Asset Integrity — the strongest named contact across all ten accounts. Lead with him.', array['Offshore SPM/SAL buoy, PLEM and subsea pipeline require periodic ROV inspection — no current provider identified', 'Pipeline network is designed for pigging (ILI) only — no drone or robotic layer found', 'Swampy, creek-dominated Andoni LGA terrain is difficult for ground crews']::text[], array['Oilserv Limited built the entire pipeline/terminal system (EPCIC contractor, not an inspection vendor)', 'No dedicated inspection-robotics vendor identified']::text[]),
  ('renaissance', 'Renaissance Africa Energy', 'Consortium — former Shell SPDC JV', 'high', 'contact', 'Nigerian-led consortium (Aradel, ND Western, First E&P, Waltersmith, Petrolin) that acquired Shell’s onshore JV (SPDC) in March 2025 — 18 OMLs, the Bonny & Forcados terminals, and the Sea Eagle FPSO. Inherited a documented ~750-task maintenance backlog and hundreds of unaccounted-for wells.', 'Two live NIPEX tenders are directly relevant: Offshore Positioning/Inspection/Seabed Survey Services, and Safety & Environment Support Services (SE Inspection scope, Q3 2026 start).', array['Leaked internal Shell documents: ~750 overdue maintenance tasks and hundreds of unaccounted-for onshore wells', 'One legacy pipeline segment was internally described by Shell (2014) as “a basket” — six spills since 2010', '4 of 10 NOSDRA-logged Niger Delta spills in July 2026 alone were attributed to Renaissance', 'Basin-wide sabotage/theft makes manned pipeline inspection costly and hazardous']::text[], array['2024 USV pipeline-route survey at Bonny (Compass Survey + Unmanned Survey Solutions/UK) — a one-off Shell-era pilot, unclear if continued', 'Undisclosed drone vendor for a 2022 pipeline/wellhead surveillance initiative', 'Daily helicopter patrols and wellhead protective cages', 'Risk-Based Inspection referenced in job postings — manual/contracted, not in-house robotic']::text[]),
  ('nlng', 'NLNG (Nigeria LNG Limited)', 'JV — NNPC / Shell / TotalEnergies / Eni', 'high', 'research', 'Bonny Island LNG plant, six trains (~27 years old) plus Train 7 (90%+ complete, targeting mid-2027 commissioning). The clearest confirmed drone relationship of all ten IOCs (Arco Worldwide Services, since 2020) — but scoped to pipeline security, not plant-asset integrity.', 'No named Asset Integrity contact — approach via Vendor Management Services (vendorservices@nlng.com) and request the correct Technical Division contact. Watch NLNG’s annual “Partners Leadership Exhibition” as a relationship venue.', array['“Asset rejuvenation programme” language signals aging-plant concern across six operating trains', 'No public methodology found for storage-tank, flare-stack or jetty/marine-structure inspection', 'LNG tank confined-space entry is inherently high-risk (asphyxiation, cold injury, explosive atmosphere)', 'Ardrend Limited (robotic tank-cleaning competitor) already exhibited at NLNG’s own 2026 vendor event — the window is open now']::text[], array['Arco Worldwide Services (AWS) — VTOL drone pipeline right-of-way surveillance since 2020; Mobile Drone Operations Command Centre launched Feb 2026', 'Train 7 EPC (Saipem/Chiyoda/Daewoo) run their own construction-phase NDT', 'No confirmed plant, tank or flare robotic inspection vendor']::text[]),
  ('aradel', 'Aradel Holdings Plc', 'Indigenous — NGX Listed', 'medium', 'contact', 'Largest oil & gas company on NGX by market cap. Flagship Ogbele field (OML 54) has produced since 2005, plus OML 34, Omerelu and a modular refinery. Runs a formal in-house Risk-Based Inspection programme and an SAP S/4HANA digital-transformation project.', 'Lead with Dr. Ebenezer Ageh (Group CTO) — frame the pitch around their existing RBI and digital-transformation investments.', array['Inspection approach is a traditional, engineering-staff-led RBI programme — no drone/ROV/crawler evidence found', 'No dedicated “Asset Integrity Manager” identified — the function appears to sit under the Group CTO', 'Now effectively controls Renaissance’s much larger, higher-risk legacy asset base']::text[], array['In-house Risk-Based Inspection (RBI) programme — no named NDT/software OEM', 'SAP S/4HANA ERP + SAP Ariba (recommended) — digital procurement, not inspection', 'No named drone, ROV or crawler vendor identified']::text[]),
  ('frontier', 'Frontier Oil Ltd', 'Indigenous — Private, small', 'low', 'research', 'Small indigenous operator of the Uquo oil side (PML 10, ~66–70 staff). The Uquo gas plant itself is operated by Savannah Energy/Accugas, not Frontier — a parallel target.', 'Small budget likely — treat as a long-tail, low-effort account. Also track Savannah Energy/Accugas as the real buyer for the Uquo gas-plant side.', array['No public documentation of how wells, flowlines or the shared FUN evacuation pipeline are inspected', 'Onshore creek/swamp/mangrove terrain is difficult for foot/boat right-of-way patrol', 'No named Asset Integrity, Inspection or Maintenance title-holder found at all']::text[], array['Emval Nigeria Limited — well integrity/workover services (downhole, not topside)', 'No drone, ROV or crawler vendor identified']::text[]),
  ('oriental', 'Oriental Energy Resources', 'Indigenous — Private, family-controlled', 'medium', 'research', 'Family-controlled operator of Ebok (100M+ bbl cumulative, the largest offshore ESP deployment in West Africa) and the newly-commissioning Okwok/EMEM FPSO. Ebok’s FSO is being replaced in 2026 after a 2018 life-extension programme.', 'No named Asset Integrity contact — the Well Engineering Manager or Deputy EHSS Manager are the closest functional entry points.', array['FSO Virini Prem (in service since 2010) underwent statutory life-extension around 2018 and is only now being retired (2026)', 'The EMEM FPSO for Okwok will need a full commissioning inspection baseline once hooked up — no current subsea contractor identified', 'No public evidence of drone/UAV topside, tank or flare-stack inspection anywhere in the portfolio']::text[], array['HBA Future Energy (Singapore) + WCP — EMEM FPSO lease-and-operate O&M', 'Marine Platforms Limited performed Ebok-area subsea completions during the Afren era (pre-2015) — current status unconfirmed', 'No named drone, digital-twin or crawler vendor identified']::text[])
