insert into public.company_products (id, company_id, product_id, rationale) values
  ('amni-cp-rov', 'amni', 'rov', 'Shallow 7–14m water depth across Ima, Okoro and Tubu suits compact ROV deployment on FPSO legs, risers and the unmanned Tubu wellhead platform.'),
  ('amni-cp-crawler', 'amni', 'crawler', 'The jacket-less CoSMOS platform and remote Tubu WHP suit confined-space crawler inspection without a manned mobilisation.'),
  ('totalenergies-cp-drone', 'totalenergies', 'drone', 'Structural/topside drone inspection is a distinct, unaddressed need alongside the existing emissions-only AUSEA programme.'),
  ('totalenergies-cp-rov', 'totalenergies', 'rov', 'Egina and Akpo FPSO legs, risers and moorings have no confirmed robotic inspection provider.'),
  ('totalenergies-cp-platform', 'totalenergies', 'platform', 'A large, sophisticated buyer already running its own drone R&D — likely to value a data/digital-twin layer over point inspections.'),
  ('seplat-cp-drone', 'seplat', 'drone', 'A topside/flare complement to the existing rope-access NDT contract — positioned as a subcontractor, not a displacement.'),
  ('seplat-cp-rov', 'seplat', 'rov', 'Yoho and the other 1970-vintage offshore platforms have no confirmed robotic subsea inspection provider.'),
  ('seplat-cp-crawler', 'seplat', 'crawler', 'Existing tank-floor scanning is already API-653 based — a natural robotics upgrade path.'),
  ('geil-cp-rov', 'geil', 'rov', 'Direct match to the new SPM/SAL buoy, PLEM and subsea pipeline — no incumbent inspection provider found.'),
  ('geil-cp-drone', 'geil', 'drone', 'Pipeline and terminal topside monitoring across a difficult creek/swamp right-of-way.'),
  ('renaissance-cp-drone', 'renaissance', 'drone', 'Pipeline right-of-way monitoring directly addresses the documented 750-task maintenance backlog.'),
  ('renaissance-cp-crawler', 'renaissance', 'crawler', 'Onshore tank and vessel inspection across 18 OMLs of legacy infrastructure.'),
  ('renaissance-cp-rov', 'renaissance', 'rov', 'The Sea Eagle FPSO has no confirmed subsea inspection provider under the new operator.'),
  ('nlng-cp-crawler', 'nlng', 'crawler', 'Direct competitive response to Ardrend — zero-man tank cleaning/inspection is already on NLNG’s radar.'),
  ('nlng-cp-drone', 'nlng', 'drone', 'Flare-stack and jetty inspection, complementary to AWS’s security-only drone scope.'),
  ('nlng-cp-platform', 'nlng', 'platform', 'Turnaround-cycle inspection data trending across six trains plus the incoming Train 7.'),
  ('aradel-cp-platform', 'aradel', 'platform', 'Their own RBI and SAP digital-transformation investment shows real appetite for structured digital reporting.'),
  ('aradel-cp-crawler', 'aradel', 'crawler', 'Ogbele and Omerelu tank/vessel inspection — no robotics vendor currently identified.'),
  ('frontier-cp-drone', 'frontier', 'drone', 'Low-cost entry point: pipeline and flowline monitoring for a small operator with limited budget.'),
  ('oriental-cp-rov', 'oriental', 'rov', 'EMEM commissioning baseline plus ongoing Ebok subsea inspection — no confirmed current provider.'),
  ('oriental-cp-cleaning', 'oriental', 'cleaning', 'Aging FSO hull and marine-growth management ahead of the 2026 replacement.')
insert into public.competitors (id, name, hq, website, notes, modality, threat) values
  ('cyberhawk', 'Cyberhawk (an Ondas company)', 'UK / USA / Qatar', 'thecyberhawk.com', 'Premium, technology-led asset-integrity data platform (iHawk). Highest price tier of the drone players researched. Not confirmed active in Nigeria — the main risk is if they enter via a supermajor framework agreement.', 'Drone', 'Adjacent'),
  ('future3d', 'THE FUTURE 3D', 'Nigeria', 'thefuture3d.com', 'Broadest verified IOC/NOC client list of any Nigerian drone player (states Shell, Total, Chevron, ExxonMobil, NNPC, Seplat, Oando). Positions on 24-hour response and fast mobilisation.', 'Drone', 'Direct'),
  ('aerialrobotix', 'Aerial Robotix', 'Lagos, Nigeria', 'aerial-robotix.com', 'Operating since 2016. States it pioneered BVLOS drone operations in Nigeria, monitoring up to 500km from base.', 'Drone', 'Direct'),
  ('arco', 'ARCO Worldwide Services', 'Lagos, Nigeria', 'arcoworldwide.com', 'NLNG''s confirmed drone partner since 2020 — the single clearest incumbent relationship found anywhere in our research. A live account risk at NLNG specifically.', 'Drone', 'Direct'),
  ('fugro', 'Fugro (Fugro RUE AS / Subsea Services)', 'Netherlands, West Africa network', 'fugro.com', 'Global geo-data major with ~50 vessels / ~160 ROVs group-wide. 20-year Nigerian incumbency since 2005. Not price-competitive for smaller scopes — a large-framework risk, not a small-deal one.', 'ROV', 'Adjacent'),
  ('tscsubsea', 'TSC Subsea + SubseaRobotix', 'UK/global + West Africa-focused', 'tscsubsea.com', '2023-announced tech-transfer partnership pairing international NDT technique depth with a regional operator — a template Aerosub itself could copy for advanced NDT capability.', 'ROV', 'Direct'),
  ('marineplatforms', 'Marine Platforms Limited', 'Lagos, Nigeria', 'marineplatforms.com', 'The most directly relevant indigenous incumbent identified in our entire research exercise — confirmed OIMR contracts with Shell (Bonga) and TotalEnergies (Akpo, Egina), both companies we are also pursuing.', 'ROV', 'Direct'),
  ('gecko', 'Gecko Robotics', 'USA, global', 'geckorobotics.com', 'AI + wall-climbing robots feeding the Cantilever data platform. Client logos include ADNOC, Marathon, HF Sinclair — proves NOC-scale reach elsewhere. No confirmed Nigeria deployment — the clearest whitespace flag in the whole competitive set.', 'Crawler', 'Adjacent'),
  ('petrobot', 'PetroBot', 'India-headquartered, active in Nigeria', 'petrobot-global.com/ng', 'India/ONGC-HPCL funded robotic tank-inspection specialist with a dedicated Nigeria service line — proof that non-Western entrants are actively targeting this niche too, not just UK/US firms.', 'Crawler', 'Direct'),
  ('ardrend', 'Ardrend Limited', 'Nigeria, sub-Saharan Africa', 'ardrend.com', 'The clearest genuinely indigenous player in the robotic tank-cleaning niche. Already has a relationship-building foothold at NLNG — our most time-sensitive competitive risk.', 'Crawler', 'Direct')
insert into public.competitor_campaigns (id, competitor_id, title, type, date, source_url, relevance, summary, performance, gap, sweet_spot, verdict) values
  ('cyberhawk-cp0', 'cyberhawk', 'Partnership with Skygauge Robotics for contact-UT thrust-vectoring drones', 'Current', '2024-01-01'::date, 'https://thecyberhawk.com/news/cyberhawk-partners-with-skygauge-robotics-to-deliver-cutting-edge-ultrasonic-thickness-inspections-to-customers-globally', 'Direct overlap', 'Adds contact-UT capability to their drone line — claimed 5–20x faster and up to 95% cheaper than rope access. Directly overlaps with Aerosub''s aerial + crawler UT positioning.', 'Actively marketed globally through 2024–25, positioned as a premium upgrade path — no specific win/loss data disclosed.', 'No confirmed Nigeria presence or local-content story.', 'Nigeria/West Africa itself — their cost premium and lack of local presence leaves room for a locally-delivered equivalent.', 'partner'),
  ('cyberhawk-cp1', 'cyberhawk', 'Five-year drone inspection & survey contract with a major Middle East LNG producer', 'Current', '2024-06-01'::date, 'https://thecyberhawk.com/oil-gas-marine', 'Watch', 'Shows appetite for long-term LNG framework agreements — relevant precedent given NLNG is one of our own target accounts.', 'Won and running — a live long-term reference account proving LNG-scale drone contracts of this size exist.', 'No African LNG account (yet).', 'Use this exact precedent in our own NLNG pitch, then differentiate on local delivery and price.', 'avoid'),
  ('future3d-cp0', 'future3d', 'Reality-capture & drone survey services across Nigeria''s six geopolitical zones', 'Current', '2025-01-01'::date, 'https://www.thefuture3d.com/locations/nigeria/', 'Direct overlap', 'Trimble X12 + DJI Matrice 350 RTK + LiDAR stack. Single-modality (drone only) — no ROV or crawler line, unlike Aerosub.', 'Established, ongoing service with a broad blue-chip client list — the most credible single-modality drone competitor in-market.', 'Drone only — no ROV or crawler, so they cannot respond to a bundled multi-domain scope alone.', 'Any account wanting subsea or confined-space work alongside drone — a bundled RFP structurally excludes them.', 'complement'),
  ('aerialrobotix-cp0', 'aerialrobotix', 'BVLOS pipeline/asset monitoring + OGI methane inspection line', 'Current', '2025-01-01'::date, 'https://aerial-robotix.com/', 'Direct overlap', 'Long-range BVLOS pipeline surveillance plus flare/tank/pipeline asset-integrity inspection. Reported partnership with Tekever AR3.', 'Established, credible operator on BVLOS surveillance/monitoring since 2016.', 'Positioning is monitoring/surveillance-led — no claimed engineering-grade NDT/defect-quantification depth.', 'Structural, UT-grade inspection work where a surveillance-only offering falls short.', 'complement'),
  ('arco-cp0', 'arco', 'NLNG Mobile Drone Operations Command Centre (MDOC) launch', 'Current', '2026-02-01'::date, 'https://www.arise.tv/nlng-arco-launch-nigerias-first-mobile-drone-control-system-in-rivers/', 'Direct overlap', 'Retrofitted Sprinter van + "Sky Whale" VTOL drone for pipeline right-of-way security. Scoped to security/surveillance, not structural inspection — our opening is still there.', 'Live, growing relationship at NLNG since 2020, just expanded Feb 2026 — strong incumbency on this specific scope.', 'Scoped to pipeline security surveillance only — no evidence of structural or asset-integrity inspection capability.', 'NLNG''s tank, flare-stack and jetty inspection — a completely different budget line, untouched by this relationship.', 'complement'),
  ('fugro-cp0', 'fugro', 'IRM air-diving/topside services for Shell/SPDC on Forcados & Bonny (origin contract)', 'Past', '2005-01-01'::date, 'https://energy-oil-gas.com/news/fugro-rue-as-leading-subsea-services-in-norway-and-west-africa/', 'Watch', 'Establishes their depth of incumbency on exactly the legacy Shell/Renaissance assets we are targeting.', '20-year incumbency, deep resource base (~50 vessels / ~160 ROVs group-wide) — the regional benchmark for ROV/subsea scale.', 'Not price-competitive for smaller scopes; likely slower and costlier to mobilise for a single-platform job.', 'Small-to-mid-scope ROV inspection jobs beneath their minimum deal size.', 'avoid'),
  ('tscsubsea-cp0', 'tscsubsea', 'Partnership announced to bring advanced NDT/structural-integrity inspection to Nigeria''s offshore sector', 'Current', '2023-11-01'::date, 'https://www.bindt.org/News/november-2023/tsc-subsea-and-subsearobotix-bring-combined-expertise-to-nigerias-subsea-inspection-market/', 'Direct overlap', 'Explicitly targets "aging infrastructure" across Nigeria/West Africa — the same demand driver behind our own pitch.', 'Partnership announced Nov 2023, explicitly targeting aging Nigerian infrastructure — still early, no confirmed contract awards found.', 'A newly-formed partnership, not yet a proven local track record.', 'The same aging-infrastructure accounts (Renaissance, Seplat) — move before they establish a track record there.', 'compete'),
  ('marineplatforms-cp0', 'marineplatforms', 'OIMR contracts with Shell (Bonga) and TotalEnergies (Akpo, Egina); historical Ebok-area work for Oriental Energy', 'Current', '2025-01-01'::date, 'https://marineplatforms.com/services-1/subsea-solutions/', 'Direct overlap', 'Work-class ROVs to 10,000+ ft. Directly overlaps with our TotalEnergies and Oriental Energy targeting — verify current contract status before proposing there.', 'Confirmed, live OIMR contracts with Shell (Bonga) and TotalEnergies (Akpo, Egina) — the strongest indigenous ROV incumbent found in this research.', 'No confirmed drone or crawler capability — ROV/subsea only.', 'Bundled inspection scopes spanning topside (drone) + confined-space (crawler) alongside subsea — they''d need to subcontract those pieces to us.', 'complement'),
  ('gecko-cp0', 'gecko', 'Case study: "global oil and gas leader" saved $1M in tank-shell costs, cut inspection time from 5 weeks to 3 days', 'Past', '2024-01-01'::date, 'https://www.geckorobotics.com/oil-and-gas', 'Watch', 'If they enter Nigeria, their Cantilever data platform is the closest thing to our own "Digital Asset-Integrity Platform" product — worth monitoring for signs of a Nigeria/West Africa push.', 'Proven ROI case study (5 weeks → 3 days, $1M saved) with blue-chip references (ADNOC, Marathon, HF Sinclair) — a credible global leader.', 'No confirmed Nigeria/West Africa deployment — the clearest whitespace in the entire competitive set.', 'Be the first mover on a Cantilever-style data platform for Nigerian/West African accounts before they arrive.', 'watch'),
  ('petrobot-cp0', 'petrobot', 'ITIS Rover + MagRover in-service tank inspection, Nigeria service line launched', 'Current', '2025-01-01'::date, 'https://petrobot-global.com/ng/services/tank-inspection', 'Direct overlap', 'ATEX/PESO certified, API 653-aligned. Directly competes with our Crawler Confined-Space Inspection product at any tank-owning account (NLNG, Aradel, Seplat).', 'Actively pushing into Nigeria with a dedicated local service line and India/ONGC-HPCL-backed R&D credibility.', 'No named Nigerian clients found yet — still building initial local references.', 'Tank-owning accounts (NLNG, Aradel, Seplat) — move before PetroBot lands its first Nigerian reference contract.', 'compete'),
  ('ardrend-cp0', 'ardrend', 'Exhibited at NLNG''s 10th "Partners Leadership Exhibition"', 'Current', '2026-01-01'::date, 'https://www.linkedin.com/posts/ardrend-limited_robotictankcleaning-ardrendlimited-nlng-activity-7444424615558348801-Lhze', 'Direct overlap', 'First NUPRC-approved provider of zero-man robotic tank cleaning/inspection in Nigeria. No confirmed contract award yet — this is a live, closing window at NLNG.', 'First NUPRC-approved zero-man tank robotics provider in Nigeria, actively exhibiting at NLNG''s own vendor event — strong early positioning, no confirmed contract award yet.', 'Small, single-modality (crawler/tank) player — no drone or ROV line.', 'A broader multi-domain pitch at NLNG that a tank-only specialist can''t match — or focus effort on accounts where they haven''t built a foothold.', 'compete')
