insert into public.events (id, name, organizer, location, start_date, end_date, cost, currency, website, benefits, notes) values
  ('adipec2026', 'ADIPEC 2026', 'ADNOC / dmg events', 'Abu Dhabi, UAE', '2026-11-09'::date, '2026-11-12'::date, '~$2,500–5,000 delegate pass; exhibition stand from ~$15,000 (approx. — confirm with organizer)', 'USD', 'adipec.com', array['The largest global O&G exhibition — direct access to OEMs, majors and NOCs from outside West Africa', 'Where global robotics/inspection players (Gecko Robotics, Cyberhawk-tier competitors) exhibit — high-value competitive intelligence', 'Strong venue for scouting OEM/technology-transfer partners (subsea tooling, NDT sensor makers)']::text[], 'Dates are typical scheduling for this recurring event — confirm exact 2026 dates against adipec.com before booking travel.'),
  ('nog2027', 'NOG Energy Week 2027', 'Nigeria Oil & Gas / Ministry of Petroleum Resources', 'Abuja, Nigeria', '2027-02-22'::date, '2027-02-26'::date, '~$800–1,500 delegate pass (approx. — confirm with organizer)', 'USD', 'nigeriaoilandgas.com', array['The single most important Nigerian upstream event — nearly every IOC on our account list typically attends', 'Direct face time with NUPRC/NCDMB regulators — relevant to vendor pre-qualification and local-content positioning', 'High density of decision-makers in one place — efficient way to advance several accounts in a single trip']::text[], 'Illustrative date based on typical Feb/March scheduling — confirm against the official site once announced.'),
  ('naice2027', 'SPE NAICE 2027', 'Society of Petroleum Engineers (Nigeria Council)', 'Lagos, Nigeria', '2027-08-03'::date, '2027-08-05'::date, '~$500–1,200 delegate pass (approx. — confirm with organizer)', 'USD', 'spenaice.org', array['Technical/engineering-led audience — a strong fit for Aerosub''s "engineering-grade analysis" positioning, not just a sales floor', 'Seplat''s CEO spoke on asset integrity and obsolescence at NAICE 2026 — this audience is already primed for our exact pitch', 'Good venue for panel/speaking-slot visibility rather than just a booth']::text[], 'Illustrative date based on the August 2026 edition — confirm against spenaice.org once the 2027 dates are published.'),
  ('nies2027', 'Nigeria International Energy Summit (NIES) 2027', 'NIES Secretariat / NUPRC', 'Abuja, Nigeria', '2027-07-13'::date, '2027-07-16'::date, '~$600–1,200 delegate pass (approx. — confirm with organizer)', 'USD', 'niessummit.com', array['TotalEnergies presented its Nigeria strategy at NIES 2026, and Aradel won "Best Full-Field Integrated Operator" there — high-visibility for both target accounts', 'Strong policy/strategy focus — good for relationship-building with leadership rather than technical buyers']::text[], 'Illustrative date — confirm against the official NIES site once the 2027 schedule is published.'),
  ('otc2027', 'Offshore Technology Conference (OTC) 2027', 'OTC / Energy4Sea', 'Houston, USA', '2027-05-03'::date, '2027-05-06'::date, '~$1,500–3,000 delegate pass; exhibition space from ~$40/sq ft (approx. — confirm with organizer)', 'USD', 'otcnet.org', array['The global benchmark event for offshore/subsea technology — best single venue for ROV, crawler and marine-growth-cleaning OEM partnerships', 'Where players like Fugro, Oceaneering and Gecko Robotics showcase new capability — direct competitive intelligence', 'Useful for benchmarking Aerosub''s own technology roadmap against the state of the art']::text[], 'OTC is consistently held in early May — confirm exact 2027 dates against otcnet.org.'),
  ('nlngexpo2027', 'NLNG & Partners Leadership Exhibition (11th edition)', 'Nigeria LNG Limited', 'Port Harcourt, Nigeria', '2027-03-01'::date, '2027-03-02'::date, 'Vendor exhibition — cost typically covers stand/booth only (confirm with NLNG Vendor Management Services)', 'USD', 'nlng.com', array['Direct vendor-relationship-building venue at one of our highest-priority accounts — Ardrend (a direct competitor) exhibited robotic tank cleaning at the 10th edition', 'A concrete, time-sensitive opportunity to get in front of NLNG''s Technical Division before a competitor closes the tank-inspection gap']::text[], 'Exact 2027 date not yet confirmed — the 10th edition ran in 2026. Contact NLNG Vendor Management Services (vendorservices@nlng.com) for the official 11th-edition schedule.')
